import sys

n, d = map(int, sys.stdin.read().split())
M = 10**9 + 7
dp = [1] * 26
for _ in range(n - 1):
    new = [0] * 26
    for c in range(26):
        for e in range(26):
            if abs(c - e) <= d:
                new[c] += dp[e]
    dp = [x % M for x in new]
print(sum(dp) % M)

